-- Additive release; historical orders and current RLS ownership are preserved.
create schema if not exists psb_private;
revoke all on schema psb_private from public, anon, authenticated;

create table public.psb_catalog_products (
  slug text primary key,
  product_name text not null,
  category_slug text not null,
  variations jsonb not null check (jsonb_typeof(variations)='array'),
  tiers jsonb,
  allowed_sellers text[],
  updated_at timestamptz not null default now()
);
alter table public.psb_catalog_products enable row level security;
revoke all on public.psb_catalog_products from public,anon,authenticated;
grant select on public.psb_catalog_products to anon,authenticated;
grant insert,update,delete on public.psb_catalog_products to authenticated;
create policy catalog_public_read on public.psb_catalog_products for select to anon,authenticated using(true);
create policy catalog_admin_insert on public.psb_catalog_products for insert to authenticated with check((select public.psb_is_admin()));
create policy catalog_admin_update on public.psb_catalog_products for update to authenticated using((select public.psb_is_admin())) with check((select public.psb_is_admin()));
create policy catalog_admin_delete on public.psb_catalog_products for delete to authenticated using((select public.psb_is_admin()));

-- Explicit public projection; never expose login, Pix, credentials or seller_payload.
create table public.psb_public_sellers (
  seller_id text primary key,
  seller_name text not null,
  label text,
  phone text,
  city text,
  status text
);
alter table public.psb_public_sellers enable row level security;
revoke all on public.psb_public_sellers from public,anon,authenticated;
grant select on public.psb_public_sellers to anon,authenticated;
create policy public_sellers_read on public.psb_public_sellers for select to anon,authenticated using(true);
insert into public.psb_public_sellers select seller_id,seller_name,label,phone,city,status from public.psb_sellers;
create function psb_private.sync_public_seller() returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
  if TG_OP='DELETE' then delete from public.psb_public_sellers where seller_id=old.seller_id;return old;end if;
  insert into public.psb_public_sellers values(new.seller_id,new.seller_name,new.label,new.phone,new.city,new.status)
  on conflict(seller_id) do update set seller_name=excluded.seller_name,label=excluded.label,phone=excluded.phone,city=excluded.city,status=excluded.status;
  return new;
end $$;
revoke all on function psb_private.sync_public_seller() from public,anon,authenticated;
create trigger psb_sync_public_seller after insert or update or delete on public.psb_sellers for each row execute function psb_private.sync_public_seller();

-- New identifiers coexist with historical eight-digit numbers.
alter table public.psb_orders drop constraint psb_orders_number_format_check;
alter table public.psb_orders add constraint psb_orders_number_format_check check(order_number ~ '^PSB-([0-9]{8}|[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$');
do $$ declare rule text; begin
  select pg_get_expr(polwithcheck,polrelid) into rule from pg_policy where polrelid='public.psb_orders'::regclass and polname='psb_orders_insert_public';
  if rule is null or position('^PSB-[0-9]{8}$' in rule)=0 then raise exception 'Unexpected existing order policy';end if;
  rule:=replace(rule,'^PSB-[0-9]{8}$','^PSB-([0-9]{8}|[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$');
  execute 'alter policy psb_orders_insert_public on public.psb_orders with check ('||rule||')';
end $$;

-- Private idempotency keys are inserted in the same transaction as the order.
-- No Data API table endpoint and no SELECT grant for visitors.
create table psb_private.order_keys(order_number text primary key);
alter table psb_private.order_keys enable row level security;
revoke all on psb_private.order_keys from public,anon,authenticated;
grant usage on schema psb_private to anon,authenticated;
grant insert on psb_private.order_keys to anon,authenticated;
create policy insert_order_key on psb_private.order_keys for insert to anon,authenticated with check(order_number ~ '^PSB-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$');

-- INSERT-only RPC: catches only the unique idempotency key constraint.
-- It never reads orders or returns customer data, including on retries.
create function public.psb_submit_order(p_order jsonb) returns jsonb language plpgsql security invoker set search_path=pg_catalog as $$
declare constraint_name text; v_number text:=p_order->>'id';
begin
  if v_number is null or v_number !~ '^PSB-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'Invalid order identifier' using errcode='22023';end if;
  if jsonb_typeof(p_order) is distinct from 'object' or octet_length(p_order::text)>300000 then raise exception 'Invalid order' using errcode='22023';end if;
  begin
    insert into psb_private.order_keys values(v_number);
  exception when unique_violation then
    get stacked diagnostics constraint_name=CONSTRAINT_NAME;
    if constraint_name<>'order_keys_pkey' then raise;end if;
    return jsonb_build_object('confirmed',true,'order_number',v_number);
  end;
  insert into public.psb_orders(order_number,seller_id,seller_name,status,payment_released,customer,items,subtotal,timeline,order_payload,source)
  values(v_number,p_order->>'sellerId',p_order->>'sellerName','aguardando-confirmacao',false,p_order->'customer',p_order->'items',(p_order->>'subtotal')::numeric,coalesce(p_order->'timeline','[]'::jsonb),p_order,'site');
  return jsonb_build_object('confirmed',true,'order_number',v_number);
end $$;
revoke all on function public.psb_submit_order(jsonb) from public;
grant execute on function public.psb_submit_order(jsonb) to anon,authenticated;

-- Keep existing string limits, but make JSON numeric/null checks explicit.
create or replace function public.psb_order_items_valid(p_items jsonb,p_seller_id text) returns boolean language plpgsql immutable strict set search_path=pg_catalog as $$
declare i jsonb;q numeric;p numeric;
begin
 if jsonb_typeof(p_items)<>'array' then return false;end if;
 if jsonb_array_length(p_items) not between 1 and 200 then return false;end if;
 for i in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(i) is distinct from 'object' or jsonb_typeof(i->'qty') is distinct from 'number' or jsonb_typeof(i->'preco') is distinct from 'number' or jsonb_typeof(i->'nome') is distinct from 'string' then return false;end if;
  q:=(i->>'qty')::numeric;p:=(i->>'preco')::numeric;
  if q not between 1 and 10000 or trunc(q)<>q or p not between 0 and 1000000 then return false;end if;
  if length(btrim(i->>'nome')) not between 1 and 200 or length(coalesce(i->>'variacao',''))>240 or length(coalesce(i->>'sellerName',''))>160 or length(coalesce(i->>'sellerLabel',''))>200 or length(coalesce(i->>'key',''))>300 or length(coalesce(i->>'img',''))>500 then return false;end if;
  if coalesce(i->>'slug','')<>'' and (length(i->>'slug')>120 or i->>'slug' !~ '^[a-z0-9][a-z0-9-]*$') then return false;end if;
  if coalesce(i->>'sellerId','')<>'' and i->>'sellerId'<>p_seller_id then return false;end if;
 end loop;return true;
end $$;

-- Validate against public commercial data while retaining the caller's RLS.
create function public.psb_validate_order_catalog() returns trigger language plpgsql security invoker set search_path=pg_catalog as $$
declare i jsonb; p public.psb_catalog_products%rowtype; v jsonb; q numeric; price numeric; total numeric:=0; permitted boolean; seen text[]:='{}'; item_key text; canonical_items jsonb:='[]';
begin
 if not public.psb_order_items_valid(new.items,new.seller_id) then raise exception 'Invalid items' using errcode='23514';end if;
 if not exists(select 1 from public.psb_public_sellers where seller_id=new.seller_id and status='approved') then raise exception 'Seller unavailable' using errcode='23514';end if;
 for i in select value from jsonb_array_elements(new.items) loop
  select * into p from public.psb_catalog_products where slug=i->>'slug';
  if not found then raise exception 'Product unavailable' using errcode='23514';end if;
  if p.allowed_sellers is not null and not new.seller_id=any(p.allowed_sellers) then raise exception 'Seller unavailable for product' using errcode='23514';end if;
  select coalesce(
    (select true from public.psb_seller_offers where seller_id=new.seller_id and scope='product' and product_slug=p.slug and active is true limit 1),
    (select active from public.psb_seller_offers where seller_id=new.seller_id and scope='category' and category_slug=p.category_slug limit 1),
    (select active from public.psb_seller_offers where seller_id=new.seller_id and scope='all' limit 1),false) into permitted;
  if not permitted then raise exception 'Seller unavailable for product' using errcode='23514';end if;
  select value into v from jsonb_array_elements(p.variations) where value->>'label'=i->>'variacao';
  if v is null then raise exception 'Variation unavailable' using errcode='23514';end if;
  item_key:=p.slug||E'\n'||(v->>'label');
  if item_key=any(seen) then raise exception 'Duplicate item' using errcode='23514';end if;
  seen:=array_append(seen,item_key);q:=(i->>'qty')::numeric;price:=(v->>'preco')::numeric;
  if p.tiers is not null then
    price:=(p.tiers->>'base')::numeric;
    if q>=coalesce((p.tiers->>'bulkMinQty')::numeric,1000001) then price:=(p.tiers->>'bulkPrice')::numeric;end if;
    if q>=coalesce((p.tiers->>'superBulkMinQty')::numeric,1000001) then price:=(p.tiers->>'superBulkPrice')::numeric;end if;
  end if;
  if price is null or (i->>'preco')::numeric<>price then raise exception 'Price changed; reload catalog' using errcode='23514';end if;
  total:=total+round(q*price,2);
  canonical_items:=canonical_items||jsonb_build_array(i||jsonb_build_object('nome',p.product_name,'categoria',p.category_slug,'preco',price,'sellerId',new.seller_id));
 end loop;
 if new.subtotal<>total then raise exception 'Subtotal mismatch' using errcode='23514';end if;
 new.items:=canonical_items;
 select seller_name into new.seller_name from public.psb_public_sellers where seller_id=new.seller_id;
 new.order_payload:=new.order_payload||jsonb_build_object('sellerName',new.seller_name,'items',new.items,'subtotal',new.subtotal);
 return new;
end $$;
revoke all on function public.psb_validate_order_catalog() from public,anon,authenticated;
create trigger trg_psb_orders_05_validate_catalog before insert on public.psb_orders for each row execute function public.psb_validate_order_catalog();

-- Escape only fields actually changed, so status updates do not encode them twice.
create or replace function public.psb_sanitize_order_html() returns trigger language plpgsql set search_path=pg_catalog as $$
begin
 if TG_OP='INSERT' then
  new.seller_name:=public.psb_html_escape_text(coalesce(new.seller_name,''));
  new.customer:=public.psb_html_escape_jsonb(new.customer);new.items:=public.psb_html_escape_jsonb(new.items);
  new.timeline:=public.psb_html_escape_jsonb(new.timeline);new.order_payload:=public.psb_html_escape_jsonb(new.order_payload);
 else
  if new.seller_name is distinct from old.seller_name then new.seller_name:=public.psb_html_escape_text(coalesce(new.seller_name,''));end if;
  if new.customer is distinct from old.customer then new.customer:=public.psb_html_escape_jsonb(new.customer);end if;
  if new.items is distinct from old.items then new.items:=public.psb_html_escape_jsonb(new.items);end if;
  if new.timeline is distinct from old.timeline then new.timeline:=public.psb_html_escape_jsonb(new.timeline);end if;
  if new.order_payload is distinct from old.order_payload then new.order_payload:=public.psb_html_escape_jsonb(new.order_payload);end if;
 end if;return new;
end $$;

